class Animal:
    def __init__(self, nome):
        self.nome = nome

    def falar(self):
        return '...'

class Cachorro(Animal):
    def falar(self):
        return 'Au au!'

class Gato(Animal):
    def falar(self):
        return 'Miau!'

animais = [Cachorro('Rex'), Gato('Mimi')]
for a in animais:
    print(f'{a.nome}: {a.falar()}')

def cronometrar(func):
    import time
    def wrapper(*args, **kwargs):
        inicio = time.time()
        resultado = func(*args, **kwargs)
        fim = time.time()
        print(f'{func.__name__} levou {fim-inicio:.4f}s')
        return resultado
    return wrapper

@cronometrar
def calcular_soma(n):
    return sum(range(n))

resultado = calcular_soma(1000000)
print(f'Soma: {resultado}')
